// Des: Tests the command dispatcher against the mock Oracle site
// Flo: parse argv > dispatch in the rig > check output lines, records, exit codes, typed errors
// I/O: none (mock site on loopback, scratch profile) > pass or fail (skips without Chrome)
// Run: cd E:\zz-base-home\as-apps\in-inte\or-orac-webs && zig build test -Dfile=ct-ctrl-runz-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const runz = @import("ct-ctrl-runz.zig"); const targ = @import("ct-ctrl-args.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
fn go(rig: *rigz.Rig, argv: []const []const u8) !u8 { rig.conf.noti_chai_orde = &.{"file"}; rig.conf.capz_help_dayz = 99; rig.conf.capz_acce_dayz = 99; rig.conf.capz_acct_dayz = 99; var cx = rig.ctx(.dry); cx.statd = try std.fmt.allocPrint(cx.aren, ".zig-cache/tmp/{s}", .{rig.tmpz.sub_path}); cx.dataroot = cx.statd; cx.grant = "nobody-zz:(OI)(CI)F"; const args = try targ.argsRead(argv); cx.mode = args.mode(); return runz.dispatch(&cx, args); }
test "status --json is valid JSON with all 7 caps and no browser used" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "status", "--json" })); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const val = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), std.mem.trim(u8, rig.sink.items, "\n"), .{}); try std.testing.expectEqualStrings("or", val.object.get("app").?.string); try std.testing.expectEqual(@as(usize, 7), val.object.get("caps").?.array.items.len); }
test "needBrow: only live runs and owner tools open the browser" { try std.testing.expect(!runz.needBrow(try targ.argsRead(&.{ "run", "login" }))); try std.testing.expect(runz.needBrow(try targ.argsRead(&.{ "run", "login", "--live" }))); try std.testing.expect(runz.needBrow(try targ.argsRead(&.{"map"}))); try std.testing.expect(runz.needBrow(try targ.argsRead(&.{"doctor"}))); try std.testing.expect(!runz.needBrow(try targ.argsRead(&.{"jobs"}))); try std.testing.expect(!runz.needBrow(try targ.argsRead(&.{ "flow", "run", "x" }))); try std.testing.expect(runz.needBrow(try targ.argsRead(&.{ "flow", "run", "x", "--live" }))); }
test "run --live via dispatch works; pause stops the next run; resume allows it" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "run", "feedback-send", "--live", "--text", "via dispatch" })); try std.testing.expect(rig.waitPre("btn|Send|via dispatch", 3000)); _ = try go(&rig, &.{"pause"}); try std.testing.expectError(error.Paused, go(&rig, &.{ "run", "feedback-send", "--live", "--text", "while paused" })); _ = try go(&rig, &.{"resume"}); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "run", "feedback-send", "--live", "--text", "after resume" })); }
test "ask understands plain words and runs the job, raw mode passes params" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "ask", "start instance ci-box", "--live" })); try std.testing.expect(rig.waitPre("btn|Start instance", 3000)); try std.testing.expect(has(&rig, "understood: inst-start")); try std.testing.expectError(error.BadUsage, go(&rig, &.{ "ask", "tell me a joke" })); rig.sink.clearRetainingCapacity(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "run", "inst-start", "--live", "--title", "ci-box" })); try std.testing.expect(rig.waitPre("btn|ci-box", 3000)); }
test "log command prints what happened" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try go(&rig, &.{ "run", "feedback-send", "--live", "--text", "x" }); _ = rig.waitRec("btn", 3000).?; rig.sink.clearRetainingCapacity(); _ = try go(&rig, &.{"log"}); try std.testing.expect(has(&rig, "ok")); try std.testing.expect(has(&rig, "help")); }
test "unlock clears an unsure key; usage errors" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.store.keyTake("some|key", 1); _ = try go(&rig, &.{ "unlock", "some|key" }); try std.testing.expectEqual(@import("st-stat-main.zig").Take.go, try rig.store.keyTake("some|key", 2)); try std.testing.expectError(error.BadUsage, go(&rig, &.{"unlock"})); try std.testing.expectError(error.NoJob, go(&rig, &.{ "run", "nope" })); try std.testing.expectError(error.BadUsage, go(&rig, &.{"run"})); try std.testing.expectError(error.BadUsage, go(&rig, &.{"zzz"})); }
test "login succeeds on a normal page and times out on the login page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_time_seco = 1; try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{"login"})); try std.testing.expect(has(&rig, "logged in")); var cx = rig.ctx(.dry); cx.base = try std.fmt.allocPrint(cx.aren, "{s}/login", .{rig.base()}); try std.testing.expectError(error.Timeout, runz.dispatch(&cx, try targ.argsRead(&.{"login"}))); }
test "halt during a live run is logged and shows in status" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectError(error.Halted, go(&rig, &.{ "run", "page-open", "--live", "--url", "/suspended" })); rig.sink.clearRetainingCapacity(); _ = try go(&rig, &.{ "status", "--json" }); try std.testing.expect(has(&rig, "\"last_halt\":\"checkpoint\"")); }
test "jobs lists every job with its risk and hint, routines too" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.flow_list = &.{.{ .name = "morning", .jobs = &.{.{ .job = "usage-view" }} }}; _ = try go(&rig, &.{"jobs"}); try std.testing.expect(has(&rig, "signup")); try std.testing.expect(has(&rig, "key-revoke")); try std.testing.expect(has(&rig, "X (needs OK)")); try std.testing.expect(has(&rig, "cap:mone")); try std.testing.expect(has(&rig, "routine morning: 1 jobs")); }
test "plan, approve and flow run as commands: risky item waits for one approval, then runs" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.flow_list = &.{.{ .name = "morning", .jobs = &.{ .{ .job = "usage-view" }, .{ .job = "key-revoke" } } }}; _ = try go(&rig, &.{ "plan", "morning" }); try std.testing.expect(has(&rig, "2. [NEEDS OK] key-revoke")); try std.testing.expect(has(&rig, "or-orac-webs approve all")); _ = try go(&rig, &.{ "approve", "all" }); try std.testing.expect(has(&rig, "approved: 1 item(s)")); _ = try go(&rig, &.{ "approve", "all" }); try std.testing.expect(has(&rig, "approved: 0 item(s)")); _ = try go(&rig, &.{ "flow", "run", "morning", "--live" }); try std.testing.expect(rig.waitPre("btn|Delete key", 4000)); try std.testing.expect(has(&rig, "2 done")); }
test "setup saves consent only with --yes; live is refused without it" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try rig.store.metaSet("consent", 0); try std.testing.expectError(error.NoConsent, go(&rig, &.{ "run", "usage-view", "--live" })); rig.conf.brow_time_seco = 2; _ = try go(&rig, &.{"setup"}); try std.testing.expect(has(&rig, "To accept and turn on live runs, run: or-orac-webs setup --yes")); try std.testing.expectError(error.NoConsent, go(&rig, &.{ "run", "usage-view", "--live" })); _ = try go(&rig, &.{ "setup", "--yes" }); try std.testing.expect(has(&rig, "consent saved")); _ = try go(&rig, &.{ "run", "feedback-send", "--live", "--text", "ok" }); try std.testing.expect(rig.waitPre("btn|Send|ok", 4000)); }
test "owner tools as commands: doctor, map, snap, report, backup, export, purge, resume" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; _ = try go(&rig, &.{ "doctor", "feedback-send" }); try std.testing.expect(has(&rig, "doctor: 1 ok, 0 missing")); _ = try go(&rig, &.{ "snap", "/billing/invoices", "bill" }); try std.testing.expect(has(&rig, "saved ")); _ = try go(&rig, &.{"report"}); try std.testing.expect(has(&rig, "report saved")); _ = try go(&rig, &.{"backup"}); try std.testing.expect(has(&rig, "backup saved")); _ = try go(&rig, &.{"export"}); try std.testing.expect(has(&rig, "exported")); _ = try go(&rig, &.{"purge"}); try std.testing.expect(has(&rig, "purged")); try rig.store.metaSet("unsafe_until", @import("ru-wait-hand.zig").realMs(rig.iozz) + 100000); _ = try go(&rig, &.{"resume"}); try std.testing.expectEqual(@as(i64, 0), try rig.store.metaGet("unsafe_until")); try std.testing.expectError(error.BadUsage, go(&rig, &.{"snap"})); try std.testing.expectError(error.BadUsage, go(&rig, &.{ "flow", "run" })); try std.testing.expectError(error.BadFlow, go(&rig, &.{ "flow", "run", "nope" })); }
test "map crawls the mock, stores controls and reports gaps" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; _ = try go(&rig, &.{"map"}); try std.testing.expect(has(&rig, "map: ")); try std.testing.expect(!has(&rig, "map: 0 pages")); try std.testing.expect((try rig.store.mapCount(try std.fmt.allocPrint(rig.aren.allocator(), "{s}/billing/invoices", .{rig.base()}))) > 3); }
test "map discovers real routes from links, skips logout and outside links, writes the report file" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; _ = try go(&rig, &.{"map"}); try std.testing.expect(has(&rig, "ROUTE   /billing/cost-analysis")); try std.testing.expect(has(&rig, "ROUTE   /billing/invoices")); try std.testing.expect(!has(&rig, "ROUTE   /logout")); try std.testing.expect(!has(&rig, "other.example")); const pth = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/map-report.txt", .{rig.tmpz.sub_path}); const txt = try std.Io.Dir.cwd().readFileAlloc(rig.iozz, pth, rig.aren.allocator(), .limited(1 << 20)); try std.testing.expect(std.mem.find(u8, txt, "## /billing/cost-analysis") != null); try std.testing.expect(std.mem.find(u8, txt, "## /billing/invoices") != null); try std.testing.expect(std.mem.find(u8, txt, "button | Pay now") != null); }
